// Configuración centralizada de entidades soportadas.
// Reemplaza la necesidad de un workflow "Generacion de plantilla" por cada dominio.
// Mismo patrón que TEMPLATE_BUILDERS en enterprise-template-api (FastAPI).
const ENTITY_CONFIGS = {
  MEDICAMENTOS: { label: 'Medicamentos' },
  MEDICAMENTOS_COMERCIALES: { label: 'Medicamentos Comerciales' },
  INSUMOS_COMERCIALES: { label: 'Insumos Comerciales' },
  INSUMOS_GENERICOS: { label: 'Insumos Genéricos' },
  USUARIOS: { label: 'Usuarios' },
  INVENTARIO: { label: 'Inventario' },
  CONTRATOS: { label: 'Contratos' },
  ASOCIACION_SEDES_CONTRATOS: { label: 'Asociación Sedes-Contratos' },
  PROCEDIMIENTOS: { label: 'Procedimientos' },
  MANUAL_TARIFARIO: { label: 'Manual Tarifario' }
};

const input = $input.first().json;
const entity = (input.entity || '').toUpperCase();
const config = ENTITY_CONFIGS[entity];

if (!config) {
  throw new Error(`Entidad '${entity}' no soportada. Disponibles: ${Object.keys(ENTITY_CONFIGS).join(', ')}`);
}

return [{
  json: {
    template: entity,
    filename: input.filename || `plantilla_${entity.toLowerCase()}.xlsx`,
    lists: input.lists || {},
    extra: input.extra || {}
  }
}];
